export function extractCookieFromResponse(res: Response): string | null {
  try {
    const rawSetCookie = res.headers.get("set-cookie");
    if (rawSetCookie) {
      const match = rawSetCookie.match(/(acw_tc=[^;]+)/i);
      if (match) {
        return match[1];
      }
    }
  } catch {}
  return null;
}

export function attachCookieToHeaders(headers: unknown, cookieStr: string): void {
  if (!headers || !cookieStr) return;
  if (headers instanceof Headers) {
    const existing = headers.get("cookie");
    if (!existing) {
      headers.set("cookie", cookieStr);
    } else if (!existing.includes(cookieStr.split("=")[0])) {
      headers.set("cookie", `${existing}; ${cookieStr}`);
    }
    return;
  }
  if (Array.isArray(headers)) {
    let found = false;
    for (const pair of headers) {
      if (typeof pair[0] === "string" && pair[0].toLowerCase() === "cookie") {
        found = true;
        if (!pair[1].includes(cookieStr.split("=")[0])) {
          pair[1] = `${pair[1]}; ${cookieStr}`;
        }
        break;
      }
    }
    if (!found) {
      headers.push(["Cookie", cookieStr]);
    }
    return;
  }
  if (typeof headers === "object") {
    let found = false;
    for (const [k, v] of Object.entries(headers)) {
      if (k.toLowerCase() === "cookie") {
        found = true;
        if (typeof v === "string" && !v.includes(cookieStr.split("=")[0])) {
          (headers as any)[k] = `${v}; ${cookieStr}`;
        }
        break;
      }
    }
    if (!found) {
      (headers as any)["Cookie"] = cookieStr;
    }
  }
}

export function getHeader(headers: unknown, name: string): string | undefined {
  if (!headers) return undefined;
  const target = name.toLowerCase();
  if (headers instanceof Headers) {
    return headers.get(target) || undefined;
  }
  if (Array.isArray(headers)) {
    for (const [k, v] of headers) {
      if (typeof k === "string" && k.toLowerCase() === target) {
        return typeof v === "string" ? v : String(v);
      }
    }
    return undefined;
  }
  if (typeof headers === "object") {
    for (const [k, v] of Object.entries(headers)) {
      if (k.toLowerCase() === target) {
        return typeof v === "string" ? v : String(v);
      }
    }
  }
  return undefined;
}

export function setHeader(headers: unknown, name: string, value: string): void {
  if (!headers) return;
  const target = name.toLowerCase();
  if (headers instanceof Headers) {
    headers.set(name, value);
    return;
  }
  // Set the first matching entry and drop duplicates, so the gateway sees exactly one value.
  if (Array.isArray(headers)) {
    const [first, ...duplicates] = headers.flatMap((entry, i) => typeof entry[0] === "string" && entry[0].toLowerCase() === target ? [i] : []);
    if (first === undefined) headers.push([name, value]);
    else headers[first][1] = value;
    for (const i of duplicates.reverse()) headers.splice(i, 1);
    return;
  }
  if (typeof headers === "object") {
    const record = headers as Record<string, any>;
    const [first = name, ...duplicates] = Object.keys(record).filter(k => k.toLowerCase() === target);
    record[first] = value;
    for (const k of duplicates) delete record[k];
  }
}

export function removeHeader(headers: unknown, name: string): void {
  if (!headers) return;
  const target = name.toLowerCase();
  if (headers instanceof Headers) {
    headers.delete(name);
    return;
  }
  if (Array.isArray(headers)) {
    for (let i = headers.length - 1; i >= 0; i--) {
      if (typeof headers[i][0] === "string" && headers[i][0].toLowerCase() === target) {
        headers.splice(i, 1);
      }
    }
    return;
  }
  if (typeof headers === "object") {
    for (const k of Object.keys(headers)) {
      if (k.toLowerCase() === target) {
        delete (headers as Record<string, any>)[k];
      }
    }
  }
}

export function patchSseResponseFailed(text: string): string {
  if (!text.includes("response.failed") && !text.includes('"status":"failed"')) return text;
  if (text.includes('"error":{') || text.includes('"error": {')) return text;
  return text.replace(
    /("status"\s*:\s*"failed")(\s*[,}])/g,
    `$1,"error":{"code":"upstream_cluster_crash","message":"AgentRouter upstream model aborted generation mid-stream (empty error from Azure/OpenAI cluster)"}$2`
  );
}

export function wrapStreamWithBuffer(
  reader: ReadableStreamDefaultReader<Uint8Array>,
  buffered: Uint8Array[]
): ReadableStream<Uint8Array> {
  const decoder = new TextDecoder();
  const encoder = new TextEncoder();
  // Patch only frames that fail without an error payload; unchanged bytes pass through untouched.
  const patchChunk = (raw: Uint8Array): Uint8Array => {
    try {
      const text = decoder.decode(raw, { stream: true });
      const patched = patchSseResponseFailed(text);
      return patched === text ? raw : encoder.encode(patched);
    } catch {
      return raw;
    }
  };
  return new ReadableStream<Uint8Array>({
    async pull(controller) {
      if (buffered.length > 0) {
        controller.enqueue(patchChunk(buffered.shift()!));
        return;
      }
      const { value, done } = await reader.read();
      if (done) {
        const tail = decoder.decode();
        if (tail) controller.enqueue(encoder.encode(tail));
        controller.close();
      } else {
        controller.enqueue(patchChunk(value));
      }
    },
    cancel(reason) {
      return reader.cancel(reason);
    },
  });
}

